export type AiModel = {
  id: Model;
  name: string;
  description: string;
  status: string | null;
  features: string[];
  suggestions: string[];
  capabilities: {
    web_search?: "full" | "always_on";
    image_generation?: "full";
  };
  in_better_ai_subscription: boolean;
  model: string;
  provider: string;
  provider_name: string;
  provider_brand: string;
  abilities: {
    web_search?: {
      toggleable: boolean;
      native?: boolean;
    };
    image_generation?: {
      model: string;
    };
    vision?: {
      formats: string[];
    };
    system_message?: {
      supported: boolean;
    };
    temperature?: {
      supported: boolean;
    };
    tools?: {
      supported: boolean;
      limit?: number;
    };
    reasoning_effort?: {
      supported: boolean;
      options: string[];
      default: string;
    };
    thinking?: {
      supported: boolean;
    };
    streaming?: {
      supported: boolean;
    };
    auto_model_high_reasoning?: {
      supported: boolean;
    };
  };
  availability: "public" | "beta" | "internal" | "deprecated";
  speed: number;
  intelligence: number;
  requires_better_ai: boolean;
  context: number;
};

export async function getAvailableAiModels() {
  const res = await fetch("https://www.raycast.com/api/v1/ai/models", {
    next: {
      revalidate: 24 * 3600,
    },
  });
  const data = await res.json();
