};

const parseAllowedUrl = (value: string | null, requestHostname: string) => {
  if (!value) return null;

  try {
    const url = new URL(value);
    const isDevelopmentUrl = process.env.NODE_ENV === "development" && url.hostname === "localhost";
    const isAllowedHostname =
      url.hostname === "ray.so" || url.hostname.endsWith(".ray.so") || url.hostname === requestHostname;

    if ((!isDevelopmentUrl && url.protocol !== "https:") || (!isDevelopmentUrl && !isAllowedHostname)) {
      return null;
    }

    return url;
  } catch {
    return null;
  }
};

export async function GET(req: NextRequest) {
  const searchParams = req.nextUrl.searchParams;
  const urlQuery = searchParams.get("url");
  const refQuery = searchParams.get("ref");

  if (!urlQuery) {
    return NextResponse.json({ error: "Missing URL" }, { status: 400 });
  }

  if (!refQuery) {
    return NextResponse.json({ error: "Missing ref" }, { status: 400 });
  }

  const url = parseAllowedUrl(urlQuery, req.nextUrl.hostname);
  const tagId = getTagId(refQuery as refProps);

  if (!url) {
    return NextResponse.json({ error: "Invalid or unsupported URL" }, { status: 400 });
  }

  if (!tagId) {
    return NextResponse.json({ error: "Invalid ref" }, { status: 400 });
  }

  if (!process.env.DUB_TOKEN) {
    return NextResponse.json({ error: "URL shortening is unavailable" }, { status: 503 });
  }

  const dub = new Dub({ token: [REDACTED] });
  try {
    const link = await dub.links.create({
      url: url.href,
      domain: "go.ray.so",
      tagIds: [tagId],
    });
    return NextResponse.json({ link: `https://ray.so/${link.key}` });
  } catch {
    return NextResponse.json({ error: "Unable to shorten this link" }, { status: 500 });
  }
}

